// ===== EDIT THESE FIVE VALUES =====
const SENDER_NAME     = 'Your Company';              // shown as the From name
const SENDER_EMAIL    = 'your_email@gmail.com';             // must equal your SMTP username
const REPLY_TO        = 'your_email@gmail.com';             // a monitored inbox
const UNSUBSCRIBE_BASE = ''; // reply-based opt-out is used
const MODEL           = 'claude-3-5-haiku-20241022'; // Anthropic model string
const item = $input.first();
const f = item.json;

const keys = Object.keys(item.binary || {});
if (!keys.length) throw new Error('No Excel file was uploaded.');

const mode = String(f['Mode'] || 'Preview').trim();
const rawId = String(f['Campaign ID'] || '').trim();
if (mode === 'Send' && !rawId) {
  throw new Error('Send mode needs the Campaign ID printed by the Preview run (it is also in the review file name).');
}
const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
const campaignId = (rawId || 'camp_' + stamp).replace(/[^A-Za-z0-9_-]/g, '_');

return [{
  json: {
    mode,
    campaign_id: campaignId,
    campaign_type: String(f['Campaign Type'] || 'excel').trim().toLowerCase(),
    campaign_prompt: String(f['Campaign Prompt'] || '').trim(),
    call_to_action: String(f['Call To Action'] || '').trim(),
    tone: String(f['Tone'] || '').trim(),
    batch_size: Math.max(1, parseInt(f['Batch Size'], 10) || 1),
    wait_seconds: Math.max(0, parseInt(f['Seconds Between Batches'], 10) || 30),
    dry_run: String(f['Dry Run'] || 'Yes').toLowerCase().startsWith('yes'),
    sender_name: SENDER_NAME,
    sender_email: SENDER_EMAIL,
    reply_to: REPLY_TO,
    unsubscribe_base: UNSUBSCRIBE_BASE,
    model: MODEL,
  },
  binary: { data: item.binary[keys[0]] },
}];

// Trim, lowercase email, map the documented Excel headers, keep the row number.
const cfg = $('Config').first().json;

return $input.all().map((it, i) => {
  // case-insensitive header lookup
  const map = {};
  for (const k of Object.keys(it.json)) map[k.trim().toLowerCase()] = it.json[k];
  const g = (...names) => {
    for (const n of names) {
      const v = map[n.toLowerCase()];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };

  const first = g('first_name');
  const last = g('last_name');
  const email = g('email').toLowerCase();

  return {
    json: {
      row_number: i + 2, // Excel row (row 1 = headers)
      campaign_id: cfg.campaign_id,
      first_name: first,
      last_name: last,
      full_name: g('full_name') || [first, last].filter(Boolean).join(' '),
      company_name: g('company_name'),
      email,
      observed_gap: g('Observed Gaps/Signal', 'observed_gap'),
      solution: g('AI/ web Opportunity (Solution)', 'solution'),
      pitch_angle: g('Pitch Angle', 'pitch_angle'),
      consent_status: g('consent_status').toLowerCase(),
      unsubscribe_url:
        g('unsubscribe_url') ||
        (email ? `${cfg.unsubscribe_base}?email=${encodeURIComponent(email)}` : ''),
      send_status: g('send_status') || 'Pending',
      notes: g('notes'),
      // filled by Preview, edited by the operator, consumed by Send
      subject: g('subject'),
      preview_text: g('preview_text'),
      html_body: g('html_body'),
      text_body: g('text_body'),
      personalization_used: g('personalization_used'),
      risk_flags: g('risk_flags'),
    },
  };
});

const DATA = '/files'; // injected by build_workflow.py (no $env needed)
// Compliance + data gate. Blocked rows are written to the audit log here.
const fs = require('fs');
const cfg = $('Config').first().json;
const LOG_DIR = DATA + '/logs';
const LOG = LOG_DIR + '/send_log.jsonl';
fs.mkdirSync(LOG_DIR, { recursive: true });

// suppression list (unsubscribes)
const suppressed = new Set();
try {
  fs.readFileSync(DATA + '/suppression.csv', 'utf8').split(/\r?\n/).slice(1).forEach((l) => {
    const e = l.split(',')[0].trim().toLowerCase();
    if (e) suppressed.add(e);
  });
} catch (e) { /* no file yet = empty list */ }

// idempotency: campaign_id + email must not be sent twice
const alreadySent = new Set();
try {
  fs.readFileSync(LOG, 'utf8').split(/\r?\n/).filter(Boolean).forEach((l) => {
    try {
      const o = JSON.parse(l);
      if (o.status === 'sent') alreadySent.add(o.campaign_id + '|' + o.email);
    } catch (e) {}
  });
} catch (e) {}

const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const seen = new Set();
const out = [];

for (const it of $input.all()) {
  const r = it.json;
  const reasons = [];

  const validEmail = emailRe.test(r.email);
  if (!validEmail) reasons.push('invalid_email');
  if (!['opted_in', 'legitimate_interest'].includes(r.consent_status)) reasons.push('compliance_block_no_consent');
  if (validEmail && suppressed.has(r.email)) reasons.push('suppressed_unsubscribed');
  if (validEmail) {
    if (seen.has(r.email)) reasons.push('duplicate_email');
    seen.add(r.email);
  }

  if (cfg.mode === 'Send') {
    if (String(r.send_status).toLowerCase() !== 'approved') reasons.push('not_approved');
    if (!r.subject || !r.text_body || !r.html_body) reasons.push('missing_generated_content');
    if (r.risk_flags) reasons.push('unresolved_risk_flags');
    if (alreadySent.has(r.campaign_id + '|' + r.email)) reasons.push('already_sent_in_campaign');
  }

  const blocked = reasons.length > 0;
  if (blocked) {
    fs.appendFileSync(LOG, JSON.stringify({
      ts: new Date().toISOString(), run_id: $execution.id, campaign_id: cfg.campaign_id,
      mode: cfg.mode, email: r.email, row_number: r.row_number,
      status: 'skipped', reason: reasons.join(', '),
    }) + '\n');
  }
  out.push({ json: { ...r, block_reason: reasons.join(', '), eligible: !blocked } });
}
return out;

const DATA = '/files'; // injected by build_workflow.py (no $env needed)
// Builds one Anthropic /v1/messages request body per eligible row.
const fs = require('fs');
const cfg = $('Config').first().json;
const system = fs.readFileSync(DATA + '/prompts/system_prompt.txt', 'utf8');

const typeHint = {
  product: 'Promote only the product described in campaign_prompt.',
  service: 'Promote only the services described in campaign_prompt.',
  custom: 'Promote only what campaign_prompt describes.',
  excel: 'No campaign prompt is required. Build the email from the recipient fields.',
}[cfg.campaign_type] || 'Build the email from the recipient fields.';

return $input.all().map((it) => {
  const r = it.json;
  const payload = {
    campaign_type: cfg.campaign_type,
    campaign_instruction: typeHint,
    campaign_prompt: cfg.campaign_prompt || null,
    desired_call_to_action: cfg.call_to_action || null,
    tone: cfg.tone || null,
    sender: { name: cfg.sender_name },
    unsubscribe_url: r.unsubscribe_url,
    recipient: {
      first_name: r.first_name,
      last_name: r.last_name,
      full_name: r.full_name,
      company_name: r.company_name,
      observed_gap_or_signal: r.observed_gap,
      ai_web_opportunity_solution: r.solution,
      pitch_angle: r.pitch_angle,
    },
  };
  return {
    json: {
      ...r,
      request_body: {
        model: cfg.model,
        max_tokens: 1200,
        system,
        messages: [{
          role: 'user',
          content: 'Write one concise, factual outreach email. Return only the required JSON object. Include this opt-out sentence in both html_body and text_body: Reply to this email with UNSUBSCRIBE to stop future emails. Do not create or invent an unsubscribe link.\n\n' + JSON.stringify(payload, null, 2),
        }],
      },
    },
  };
});

// Parse + validate the model output. Anything doubtful -> "Needs Review".
const out = [];
const claimRe = /\bguarantee[sd]?\b|\b\d{1,3}(?:\.\d+)?\s?%|\bcase stud(?:y|ies)\b|\btrusted by\b|\b(?:clients|customers) (?:like|such as)\b|\bROI of\b/i;

$input.all().forEach((it, i) => {
  const { request_body, ...row } = $('Build Prompt').itemMatching(i).json;
  const issues = [];
  let d = {};

  if (it.json.error || !Array.isArray(it.json.content)) {
    const msg = (it.json.error && (it.json.error.message || JSON.stringify(it.json.error))) || 'no content returned';
    issues.push('ai_call_failed: ' + String(msg).slice(0, 200));
  } else {
    try {
      let t = it.json.content.filter((b) => b.type === 'text').map((b) => b.text).join('').trim();
      t = t.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
      const a = t.indexOf('{'), b = t.lastIndexOf('}');
      d = JSON.parse(t.slice(a, b + 1));
    } catch (e) {
      issues.push('invalid_json_from_ai');
    }
  }

  if (!issues.length) {
    for (const k of ['subject', 'preview_text', 'html_body', 'text_body', 'personalization_used', 'risk_flags']) {
      if (d[k] === undefined || d[k] === null) issues.push('missing_key:' + k);
    }
    const subject = String(d.subject || '');
    const text = String(d.text_body || '');
    const words = text.split(/\s+/).filter(Boolean).length;
    if (subject.length < 3 || subject.length > 70) issues.push('subject_length:' + subject.length);
    if (words < 90 || words > 150) issues.push('word_count:' + words);
    if (!/unsubscribe|opt[- ]?out/i.test(text)) issues.push('missing_unsubscribe_text');
    if (row.unsubscribe_url && !(String(d.html_body).includes(row.unsubscribe_url) && text.includes(row.unsubscribe_url))) {
      issues.push('missing_unsubscribe_link');
    }
    const m = (subject + ' ' + text).match(claimRe);
    if (m) issues.push('possible_unsupported_claim:' + m[0]);
    if (Array.isArray(d.risk_flags)) d.risk_flags.forEach((x) => issues.push('ai_flag:' + x));
  }

  out.push({
    json: {
      ...row,
      subject: String(d.subject || ''),
      preview_text: String(d.preview_text || ''),
      html_body: String(d.html_body || ''),
      text_body: String(d.text_body || ''),
      personalization_used: String(d.personalization_used || ''),
      risk_flags: issues.join('; '),
      send_status: issues.length ? 'Needs Review' : 'Pending',
    },
  });
});
return out;

// Shape generated drafts into the review spreadsheet (this file is re-uploaded in Send mode).
const cols = ['row_number', 'campaign_id', 'first_name', 'last_name', 'full_name', 'company_name', 'email',
  'consent_status', 'unsubscribe_url', 'send_status', 'subject', 'preview_text', 'text_body', 'html_body',
  'personalization_used', 'risk_flags', 'notes'];
return $input.all().map((it) => {
  const o = {};
  for (const c of cols) o[c] = it.json[c] ?? '';
  return { json: o };
});

const DATA = '/files'; // injected by build_workflow.py (no $env needed)
const fs = require('fs');
const cfg = $('Config').first().json;
const rows = $('Build Review Rows').all().map((x) => x.json);

const skipped = [];
try {
  fs.readFileSync(DATA + '/logs/send_log.jsonl', 'utf8').split(/\r?\n/).filter(Boolean).forEach((l) => {
    try {
      const o = JSON.parse(l);
      if (o.run_id === $execution.id && o.status === 'skipped') skipped.push({ row: o.row_number, email: o.email, reason: o.reason });
    } catch (e) {}
  });
} catch (e) {}

const report = {
  campaign_id: cfg.campaign_id,
  mode: 'Preview',
  generated: rows.length,
  needs_review: rows.filter((r) => r.send_status === 'Needs Review').length,
  clean_pending_approval: rows.filter((r) => r.send_status === 'Pending').length,
  approved: 0,
  sent: 0,
  failed: 0,
  skipped: skipped.length,
  skipped_details: skipped,
  review_file: `data/files/reviews/${cfg.campaign_id}_review.xlsx`,
  next_step: 'Open the review file, edit text if needed, set send_status to Approved, clear risk_flags once fixed, then run the form again with Mode = Send and this campaign_id.',
};
fs.mkdirSync(DATA + '/reports', { recursive: true });
fs.writeFileSync(`${DATA}/reports/${cfg.campaign_id}_preview.json`, JSON.stringify(report, null, 2));
return [{ json: report }];

const cfg = $('Config').first().json;
const safeName = String(cfg.sender_name).replace(/["\r\n]/g, '');
return $input.all().map((it) => ({
  json: { ...it.json, from: `"${safeName}" <${cfg.sender_email}>`, reply_to: cfg.reply_to },
}));

const DATA = '/files'; // injected by build_workflow.py (no $env needed)
// Dry run: nothing is sent. Records what WOULD be sent.
const fs = require('fs');
const cfg = $('Config').first().json;
fs.mkdirSync(DATA + '/logs', { recursive: true });
return $input.all().map((it) => {
  const r = it.json;
  fs.appendFileSync(DATA + '/logs/send_log.jsonl', JSON.stringify({
    ts: new Date().toISOString(), run_id: $execution.id, campaign_id: cfg.campaign_id, mode: 'Send',
    email: r.email, row_number: r.row_number, status: 'dry_run', subject: r.subject,
  }) + '\n');
  return { json: { email: r.email, status: 'dry_run' } };
});

const DATA = '/files'; // injected by build_workflow.py (no $env needed)
// Runs right after "Send Email". Success items carry messageId; failures carry {error}.
const fs = require('fs');
const cfg = $('Config').first().json;
fs.mkdirSync(DATA + '/logs', { recursive: true });

return $input.all().map((it, i) => {
  const j = it.json;
  let row = {};
  try { row = $('Loop Over Items').itemMatching(i).json; } catch (e) {}
  const email = row.email || (j.accepted && j.accepted[0]) || (j.envelope && j.envelope.to && j.envelope.to[0]) || '';
  const failed = !!j.error || !j.messageId;
  const rec = {
    ts: new Date().toISOString(), run_id: $execution.id, campaign_id: cfg.campaign_id, mode: 'Send',
    email, row_number: row.row_number || null,
    status: failed ? 'failed' : 'sent',
    message_id: j.messageId || null,
    error: failed ? String((j.error && (j.error.message || j.error)) || 'no messageId returned').slice(0, 300) : null,
    attempt: 1,
  };
  fs.appendFileSync(DATA + '/logs/send_log.jsonl', JSON.stringify(rec) + '\n');
  return { json: rec };
});

const DATA = '/files'; // injected by build_workflow.py (no $env needed)
const fs = require('fs');
const cfg = $('Config').first().json;
const latest = {};
const skipped = [];
try {
  fs.readFileSync(DATA + '/logs/send_log.jsonl', 'utf8').split(/\r?\n/).filter(Boolean).forEach((l) => {
    try {
      const o = JSON.parse(l);
      if (o.run_id !== $execution.id) return;
      if (o.status === 'skipped') skipped.push({ row: o.row_number, email: o.email, reason: o.reason });
      else latest[o.email] = o;
    } catch (e) {}
  });
} catch (e) {}
const vals = Object.values(latest);
const report = {
  campaign_id: cfg.campaign_id,
  mode: 'Send',
  dry_run: cfg.dry_run,
  sent: vals.filter((v) => v.status === 'sent').length,
  failed: vals.filter((v) => v.status === 'failed').length,
  would_send_dry_run: vals.filter((v) => v.status === 'dry_run').length,
  skipped: skipped.length,
  skipped_details: skipped,
  failures: vals.filter((v) => v.status === 'failed').map((v) => ({ email: v.email, error: v.error })),
};
fs.mkdirSync(DATA + '/reports', { recursive: true });
fs.writeFileSync(`${DATA}/reports/${cfg.campaign_id}_send_${$execution.id}.json`, JSON.stringify(report, null, 2));
return [{ json: report }];
